'use strict';
const $=s=>document.querySelector(s), main=$('#main'), modal=$('#modal');
let saved={};try{saved=JSON.parse(localStorage.getItem('heat-lab-v1')||'{}')||{}}catch{}
let current=Number.isInteger(saved.current)&&saved.current>=0&&saved.current<7?saved.current:0;
let completed=new Set(Array.isArray(saved.completed)?saved.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<7):[]), sorting=false;
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const persist=()=>{try{localStorage.setItem('heat-lab-v1',JSON.stringify({current,completed:[...completed]}))}catch{$('#storage-note').textContent='Progreso disponible solo durante esta sesión.'}};
function stop(){ window.HeatScenes?.destroy(); }
function map(){ $('#map').innerHTML=LESSONS.map((l,i)=>`<button class="mission ${current===i?'active':''} ${completed.has(i)?'done':''}" data-mission="${i}" ${current===i?'aria-current="step"':''}><span>${completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span>${l.short}</button>`).join('');$('#progress').value=completed.size;$('#progress-label').textContent=`${completed.size} de 7 completadas`;document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>render(+b.dataset.mission,true))}
function openModal(title,body){$('#modal-body').innerHTML=`<h2>${title}</h2>${body}`;modal.showModal()}
$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function render(i,focus=false){stop();current=i;persist();map();const l=LESSONS[i];main.innerHTML=`<div class="topline"><span class="eyebrow">MISIÓN ${String(i+1).padStart(2,'0')} / 07</span><span class="badge">EXPERIMENTA · DESCUBRE · COMPRENDE</span></div><h1>${l.title}</h1><p class="intro">${l.intro}</p><section class="experiment" aria-label="Experimento interactivo"><div class="lab-head"><span><i class="live-dot"></i> MESA DE EXPERIMENTOS</span><span>0${i+1} — OBSERVA QUÉ CAMBIA</span></div><div class="stage" id="stage"></div><p class="model-note" id="model-note"></p></section><div class="below"><section class="explanation"><span class="eyebrow">LA IDEA QUE TE LLEVAS</span><h3 style="margin-top:10px">${l.question}</h3><p>${l.explain}</p><details><summary>Un poco más de ciencia</summary><p>${l.detail}</p></details><button class="text-button" id="glossary">Abrir diccionario de ciencia ↗</button><button class="curiosity" id="curiosity"><span>✦ SIGUE TU CURIOSIDAD</span>${l.curiosity} ↗</button></section><section class="challenge"><span class="eyebrow">PONLO A PRUEBA</span><h3 style="margin-top:10px">Un pequeño reto</h3><p>${l.challenge}</p><div class="answers">${l.answers.map((a,j)=>`<button class="answer" data-answer="${j}">${a}</button>`).join('')}</div><button class="text-button" id="hint">Necesito una pista</button><p class="feedback" id="feedback" aria-live="polite"></p></section></div><div class="navigation"><button class="outline" id="prev" ${i===0?'disabled':''}>← Anterior</button><span>La curiosidad no tiene prisa.</span><button class="primary" id="next">${i===6?'Ir al reto final':'Siguiente misión'} →</button></div>`;
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const right=+b.dataset.answer===l.answer;b.classList.add(right?'correct':'wrong');$('#feedback').textContent=right?`¡Lo descubriste! ${l.why}`:`Vuelve a observar. ${l.hint} Puedes intentarlo otra vez.`;if(right){completed.add(i);persist();map()}});$('#hint').onclick=()=>$('#feedback').textContent=l.hint;$('#curiosity').onclick=()=>openModal(l.curiosity,`<p>${l.curious}</p><p><a target="_blank" rel="noopener noreferrer" href="https://phet.colorado.edu/es/simulations/energy-forms-and-changes">Explorar en PhET ↗</a> — cambia los materiales y observa la energía.</p>`);$('#glossary').onclick=()=>openModal('Palabras para explorar','<p><b>Partícula:</b> una parte diminuta de la materia, como un átomo o una molécula.</p><p><b>Energía cinética:</b> energía asociada al movimiento.</p><p><b>Promedio:</b> suma de varios valores dividida entre cuántos hay.</p><p><b>Equilibrio térmico:</b> estado en que dos cuerpos tienen la misma temperatura y no intercambian calor neto.</p><p><b>Gradiente:</b> cómo cambia una cantidad, aquí la temperatura, con la posición.</p><p><b>Aislante térmico:</b> material que dificulta transferir calor.</p><p><b>Magnitud escalar:</b> cantidad descrita con un valor y una unidad, sin dirección.</p>');$('#prev').onclick=()=>render(i-1,true);$('#next').onclick=()=>i===6?finalQuiz():render(i+1,true);setupExperiment();if(focus)main.focus();}
function setupExperiment(){ window.HeatScenes.mount(current, {openModal, materialsModal}); }
function materialsModal(){const rows=sorting?[...MATERIALS].sort((a,b)=>b[2]-a[2]):MATERIALS;openModal('¿Qué material conduce más?',`<p>Valores de las páginas del libro, en <b>W/(m·K)</b>. Son orientativos: cambian según composición y condiciones. Las barras usan el punto medio de cada rango y escala lineal.</p><div class="table-wrap"><table><thead><tr><th>Material</th><th><button id="sort-materials">Conductividad ${sorting?'↓':'↕'}</button></th><th>Comparación</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${m[0]}</td><td>${m[1]}</td><td><div class="bar" style="width:${m[2]/378.65*100}%"></div></td></tr>`).join('')}</tbody></table></div><p>El cobre facilita transferir calor; el corcho dificulta esa transferencia. El mercurio figura como dato del libro, no como material para experimentar en casa.</p>`);$('#sort-materials').onclick=()=>{sorting=!sorting;modal.close();materialsModal()}}
function finalQuiz(){stop();main.innerHTML=`<div class="eyebrow">LA ÚLTIMA MISIÓN</div><h1>Piensa como un científico<span style="color:var(--orange)">.</span></h1><p class="intro">Cinco situaciones nuevas. Sin reloj, sin penalizaciones. Puedes volver a las misiones cuando quieras.</p>${FINAL_QUIZ.map((q,i)=>`<section class="final-card"><h3>${i+1}. ${q[0]}</h3><div class="answers">${q[1].map((a,j)=>`<button class="answer" data-final="${i}" data-choice="${j}">${a}</button>`).join('')}</div><p class="feedback" id="final-feedback-${i}" aria-live="polite"></p></section>`).join('')}<p id="final-result" aria-live="polite"></p><div class="source-links"><a target="_blank" rel="noopener noreferrer" href="https://phet.colorado.edu/es/simulations/energy-forms-and-changes">Explora energía y materiales en PhET ↗</a><a target="_blank" rel="noopener noreferrer" href="https://openstax.org/books/university-physics-volume-2/pages/1-4-heat-transfer-specific-heat-and-calorimetry">Profundiza con OpenStax (en inglés) ↗</a></div><button id="back-missions" class="outline">← Volver a las misiones</button>`;const correct=new Set();document.querySelectorAll('[data-final]').forEach(b=>b.onclick=()=>{const i=+b.dataset.final,q=FINAL_QUIZ[i],ok=+b.dataset.choice===q[2];b.classList.add(ok?'correct':'wrong');$(`#final-feedback-${i}`).textContent=ok?`Exacto. ${q[3]}`:`Piensa de nuevo: ${q[3]} Inténtalo otra vez.`;if(ok)correct.add(i);$('#final-result').textContent=correct.size===5?'¡Resolviste los cinco casos! Ahora puedes explicar cómo viaja la energía.':`${correct.size} de 5 situaciones resueltas.`});$('#back-missions').onclick=()=>render(current,true);main.focus()}
$('#library').onclick=()=>openModal('Tu cuaderno del calor',`${LESSONS.map((l,i)=>`<section><h3>${i+1}. ${l.title}</h3><p>${l.explain}</p><p>${l.detail}</p></section>`).join('')}<h3>Conductividad: valores del libro</h3><table><thead><tr><th>Material</th><th>W/(m·K)</th></tr></thead><tbody>${MATERIALS.map(m=>`<tr><td>${m[0]}</td><td>${m[1]}</td></tr>`).join('')}</tbody></table><p>Valores orientativos, dependientes de las condiciones. Se normaliza la escritura de las unidades.</p><h3>Fuentes y exploración</h3><p>Fuente principal: imagen proporcionada de la lectura 15, «El calor, la temperatura y la energía cinética», Conexiones Física 2.º, páginas 68–69. Adaptación educativa con ilustraciones originales.</p><p><a target="_blank" rel="noopener noreferrer" href="https://phet.colorado.edu/es/simulations/energy-forms-and-changes">PhET: Formas y cambios de energía ↗</a>. Experimenta con materiales y observa los cambios de energía.</p><p><a target="_blank" rel="noopener noreferrer" href="https://openstax.org/books/university-physics-volume-2/pages/1-4-heat-transfer-specific-heat-and-calorimetry">OpenStax: transferencia de calor y calorimetría (inglés) ↗</a>. Referencia para profundizar acompañado de un adulto.</p>`);
$('#final-link').onclick=finalQuiz;$('.brand').onclick=e=>{e.preventDefault();render(0,true)};$('#reset-progress').onclick=()=>openModal('¿Reiniciar tu expedición?','<p>Se borrarán las misiones completadas en este navegador.</p><button id="confirm-reset">Sí, reiniciar progreso</button>');modal.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){completed.clear();modal.close();render(0,true)}});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{reduced=e.matches;render(current)});render(current);

